(3, 1, 'Vertex Ultra 13', 'Компактный ультрабук в алюминиевом корпусе. Мгновенный отклик, длинная автономность и профессиональная цветопередача.', '{"Процессор":"Intel Core Ultra 7 155U","Память":"16 ГБ LPDDR5","Накопитель":"1 ТБ SSD","Дисплей":"13,3 дюйма, 2.5K, 90 Гц","Вес":"1,08 кг","ОС":"Windows 11 Pro"}', 79990, NULL, 12, 'laptop-ultra.svg', 0, 1, '2026-09-02 09:30:00'),
(4, 1, 'Polaris Gaming 15', 'Игровой ноутбук с дискретной графикой, эффективным охлаждением и экраном 165 Гц.', '{"Процессор":"Intel Core i7-13650HX","Память":"16 ГБ DDR5","Накопитель":"1 ТБ SSD","Дисплей":"15,6 дюйма, QHD, 165 Гц","Видеокарта":"NVIDIA GeForce RTX 4060 8 ГБ","Вес":"2,3 кг"}', 94990, 104990, 5, 'laptop-gaming.svg', 0, 1, '2026-07-18 16:40:00'),
